package structural.composite.sample;

public class File implements IFileSystemComponent {
    private final String name;

    public File(String name) {
        this.name = name;
    }

    @Override
    public void showDetails(String indent) {
        System.out.println(indent + "File: " + name);
    }
}

package structural.composite.sample;

import java.util.ArrayList;
import java.util.List;

public class Folder implements IFileSystemComponent {
    private final String name;
    private final List<IFileSystemComponent> children = new ArrayList<>();

    public Folder(String name) {
        this.name = name;
    }

    public void add(IFileSystemComponent component) {
        children.add(component);
    }

    @Override
    public void showDetails(String indent) {
        System.out.println(indent + "Folder: " + name);
        for (IFileSystemComponent child : children) {
            child.showDetails(indent + "  ");
        }
    }
}

package structural.composite.sample;

public interface IFileSystemComponent {
    void showDetails(String indent);
}

package structural.composite.sample;

public class Main {
    public static void main(String[] args) {
        Folder root = new Folder("root");
        Folder src = new Folder("src");
        File mainFile =  new File("Main.java");
        File utilsFile =  new File("Utils.java");
        File licenseFile =  new File("LICENSE.java");
        File readmeFile =  new File("README.java");

        src.add(mainFile);
        src.add(utilsFile);

        root.add(src); // Folder can contain other Folders and Files
        root.add(licenseFile);
        root.add(readmeFile);

        root.showDetails("");

    }
}

